import {renderResults,candidateKey} from './result-view.js';
import {legalMoves,trainerCap,inferLevel,recognizeCP,digitTemplates} from './observation.js';
const $=s=>document.querySelector(s), el=(tag,cls,text)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n};
const db=await fetch('data.json').then(r=>{if(!r.ok)throw Error('DB 로드 실패');return r.json()});
$('#dataInfo').textContent=`DB 확인 ${db.checkedAt.slice(0,10)} / ${db.pokemon.length}종/폼 / ${Object.keys(db.moves).length}개 기술`;
const storage=await new Promise((resolve,reject)=>{const r=indexedDB.open('go-lens-private',1);r.onupgradeneeded=()=>r.result.createObjectStore('cards',{keyPath:'id'});r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)}).catch(()=>null);
let editCalSnapshot=null;
let editing=false,saving=false,draftPvpUse='',editRevision=0;
let cards=[],selected=null,cancel=false,busy=false,videoURL=null,cal=null,calpoints=null,job=0;
try{cal=JSON.parse(localStorage.getItem('go-lens-cal')||'null')}catch{}
function status(s){$('#status').textContent=s}
async function transaction(mode,fn){if(!storage)throw Error('기기 저장소를 사용할 수 없습니다.');return new Promise((resolve,reject)=>{const t=storage.transaction('cards',mode),req=fn(t.objectStore('cards'));let value;req.onsuccess=()=>value=req.result;t.oncomplete=()=>resolve(value);t.onerror=()=>reject(t.error);t.onabort=()=>reject(t.error)})}
async function save(card){try{await transaction('readwrite',s=>s.put(card));}catch{status('기기 저장에 실패했습니다. 탭을 닫기 전에 백업을 내보내세요.')}const i=cards.findIndex(x=>x.id===card.id);if(i<0)cards.push(card);else cards[i]=card;render()}
function render(){const root=$('#cards');root.replaceChildren();$('#count').textContent=cards.length;$('#empty').hidden=!!cards.length;for(const c of [...cards].reverse()){const b=el('button','card');b.type='button';const img=el('img');img.src=c.image;img.alt=c.demo?'예제 조사 화면':`조사 화면 ${c.time?.toFixed(1)||0}초`;b.append(img);const body=el('div','cardbody');body.append(el('span','cardtag',c.demo?'예제 화면':c.confirmed?'확인 완료':'확인 필요'),el('h3',null,db.pokemon.find(p=>p.id===c.species)?.name||'포켓몬을 선택해 주세요'),el('p',null,`${c.time?.toFixed(1)||0}초 / ${c.confidence||'수동 저장'}`));const line=el('div','ivline');line.append(el('strong',null,c.iv?.every(Number.isInteger)?c.iv.join(' / '):'IV 판독 대기'),el('span',null,'분석'));body.append(line);if(c.preview?.length){const badges=el('div','cardpreviews');for(const x of c.preview)badges.append(el('span','pvpbadge',`${x.cap===1500?'슈퍼':'하이퍼'} / ${db.pokemon.find(p=>p.name===x.name||p.englishName===x.name)?.name||x.name} ${x.percentile.toFixed(1)}%`));body.append(badges)}b.append(body);b.onclick=()=>open(c);root.append(b)}}
try{cards=await transaction('readonly',s=>s.getAll());render()}catch{status('기기 저장소 사용 불가 / 현재 탭에서는 분석과 백업이 가능합니다.')}
const worker=new Worker('worker.js',{type:'module'}),pending=new Map();worker.onmessage=({data})=>{const p=pending.get(data.id);if(p){pending.delete(data.id);clearTimeout(p.timer);data.error?p.reject(Error(data.error)):p.resolve(data.result)}};worker.onerror=()=>{for(const p of pending.values()){clearTimeout(p.timer);p.reject(Error('분석 작업을 실행하지 못했습니다. 페이지를 새로 열어 주세요.'))}pending.clear()};
function calculate(data){return new Promise((resolve,reject)=>{const id=++job,timer=setTimeout(()=>{pending.delete(id);reject(Error('계산 시간이 초과되었습니다. 다시 시도해 주세요.'))},60000);pending.set(id,{resolve,reject,timer});worker.postMessage({id,db,...data})})}
function options(select,items,placeholder){select.replaceChildren();if(placeholder){const o=el('option',null,placeholder);o.value='';select.append(o)}for(const [value,label] of items){const o=el('option',null,label);o.value=value;select.append(o)}}
function speciesOptions(query='',value=''){const list=db.pokemon.filter(p=>`${p.name} ${p.englishName||''} ${p.id} ${p.dex}`.toLowerCase().includes(query.toLowerCase()));options($('#species'),list.map(p=>[p.id,`${p.name} / #${p.dex}`]),'종·폼을 직접 선택하세요');if(list.some(p=>p.id===value))$('#species').value=value;}
function getState(){return {shadow:$('#state-shadow').checked,purified:$('#state-purified').checked,lucky:$('#state-lucky').checked}}
function moveOptions(p,fast='',charged=''){const allowed=!!p?.shadowAllowed&&!p?.mega;for(const k of ['shadow','purified']){$('#state-'+k).disabled=!allowed;if(!allowed)$('#state-'+k).checked=false}let moves={fast:[],charged:[]};if(p)moves=legalMoves(db,p,getState());const label=k=>`${db.moves[k]?.name||'이름 확인 필요'}${p?.elite?.includes(k)?' / 한정/레거시':''}`;options($('#fast'),moves.fast.map(k=>[k,label(k)]),'실제 보유 기술 선택');options($('#charged'),moves.charged.map(k=>[k,label(k)]),'실제 보유 기술 선택');if(moves.fast.includes(fast))$('#fast').value=fast;if(moves.charged.includes(charged))$('#charged').value=charged;$('#state-help').textContent=allowed?'그림자·정화는 서로 배타적입니다. 정화·반짝반짝은 함께 표시할 수 있습니다. 반짝반짝은 전투 보너스가 없습니다.':'이 종·폼의 그림자·정화가 현재 데이터에 없어 선택을 제한합니다.';}

let imageObj=null;async function loadImage(src){return new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=()=>reject(Error('이미지를 읽을 수 없습니다.'));i.src=src})}
async function open(c){editing=false;editRevision++;draftPvpUse=c.pvpUse||'';if(!$('#trainer').value&&c.trainer)$('#trainer').value=c.trainer;selected=c;calpoints=null;cpPoints=null;$('#search').value='';speciesOptions('',c.species);$('#state-shadow').checked=c.shadow||false;$('#state-purified').checked=c.purified||false;$('#state-lucky').checked=c.lucky||false;moveOptions(db.pokemon.find(p=>p.id===c.species),c.fast,c.charged);['atk','def','hp'].forEach((k,i)=>$('#'+k).value=c.iv?.[i]??0);syncIV();$('#iv-confirm').checked=!!c.iv;$('#observed-cp').value=c.observed?.cp||'';$('#observed-hp').value=c.observed?.hp||'';$('#threshold').value=c.threshold??90;$('#cpfloor').value=(c.cpFloor??.9)*100;$('#error').textContent='';$('#results').replaceChildren();$('#calhelp').textContent=c.confidence||'조사 막대를 확인하고 IV 슬라이더를 조정하세요.';applyEditMode();$('#edit').disabled=true;if(!$('#detail').open)$('#detail').showModal();imageObj=await loadImage(c.image);draw();if(!c.observed?.cp)readCP();updateEstimate();if(c.confirmed)await analyze(false);applyEditMode();$('#edit').disabled=false;}

function draw(){const cv=$('#shot');cv.width=imageObj.naturalWidth;cv.height=imageObj.naturalHeight;const ctx=cv.getContext('2d');ctx.drawImage(imageObj,0,0);if(calpoints){ctx.fillStyle='#00ddff';for(const [x,y] of calpoints){ctx.beginPath();ctx.arc(x*cv.width,y*cv.height,7,0,Math.PI*2);ctx.fill()}}}
$('#search').oninput=e=>speciesOptions(e.target.value,$('#species').value);$('#species').onchange=()=>{moveOptions(db.pokemon.find(p=>p.id===$('#species').value));updateEstimate();$('#results').replaceChildren()};
$('#calibrate').onclick=()=>{cpPoints=null;calpoints=[];$('#calhelp').textContent='1/5 / 첫 막대의 왼쪽 시작점을 클릭하세요 (빈 부분 포함 전체 길이 기준).';draw()};
$('#shot').onclick=e=>{if(!editing||!calpoints)return;const cv=$('#shot'),r=cv.getBoundingClientRect(),scale=Math.min(r.width/cv.width,r.height/cv.height),dw=cv.width*scale,dh=cv.height*scale,x=(e.clientX-r.left-(r.width-dw)/2)/dw,y=(e.clientY-r.top-(r.height-dh)/2)/dh;if(x<0||x>1||y<0||y>1)return;calpoints.push([x,y]);draw();const prompts=['','첫 막대의 오른쪽 끝을 클릭하세요 (15 IV 길이).','공격 막대 중앙을 클릭하세요.','방어 막대 중앙을 클릭하세요.','HP 막대 중앙을 클릭하세요.'];if(calpoints.length<5){$('#calhelp').textContent=`${calpoints.length+1}/5 / ${prompts[calpoints.length]}`;return}const [a,b,c,d,h]=calpoints;if(b[0]-a[0]<.1||!(c[1]<d[1]&&d[1]<h[1])){$('#calhelp').textContent='좌표 순서가 올바르지 않습니다. 보정을 다시 시작하세요.';calpoints=null;return}cal={x0:a[0],x1:b[0],ys:[c[1],d[1],h[1]]};calpoints=null;draw();const result=detect(cv.getContext('2d').getImageData(0,0,cv.width,cv.height),cal);['atk','def','hp'].forEach((k,i)=>$('#'+k).value=result.iv[i]);syncIV();$('#iv-confirm').checked=false;updateEstimate();$('#calhelp').textContent='좌표 보정 완료. 판독한 IV를 확인하고 저장하세요. 같은 화면 배치에서만 유효합니다.'};
function metric(title,value,sub,right){const n=el('div','metric'),a=el('div');a.append(el('small',null,title),el('strong',null,value),el('small',null,sub));n.append(a);if(right){const b=el('div','right');b.append(el('strong',null,right[0]),el('small',null,right[1]));n.append(b)}return n}
async function analyze(persist=true){if(persist&&!editing)return;const revision=editRevision,c=selected;$('#error').textContent='';try{const p=db.pokemon.find(p=>p.id===$('#species').value);if(!p)throw Error('종과 폼을 선택하세요.');if(!$('#iv-confirm').checked)throw Error('조사 막대를 확인한 뒤 IV 확인에 체크하세요.');const iv=['atk','def','hp'].map(k=>Number($('#'+k).value)),trainer=Number($('#trainer').value),state=getState(),max=50,threshold=Number($('#threshold').value),cpFloor=Number($('#cpfloor').value)/100;trainerCap(trainer);legalMoves(db,p,state);if(!Number.isFinite(threshold)||threshold<0||threshold>100||cpFloor<0||cpFloor>1)throw Error('기준은 0–100%로 입력하세요.');const observed={cp:Number($('#observed-cp').value)||null,hp:Number($('#observed-hp').value)||null};if(observed.cp&&(!Number.isInteger(observed.cp)||observed.cp<10||observed.cp>20000)||observed.hp&&(!Number.isInteger(observed.hp)||observed.hp<10||observed.hp>2000))throw Error('CP·HP는 화면에 보이는 정수로 입력하세요.');const inference=inferLevel(db,p,iv,trainer,observed,state),level=inference.level,data={p,iv,trainer,observed,...state,max,threshold,cpFloor,fast:$('#fast').value,charged:$('#charged').value};if(persist){saving=true;applyEditMode()}$('#analyze').disabled=true;$('#analyze').textContent='레벨 / 진화 후보 / 기술 비교 중…';const r=await calculate(data);if(selected?.id!==c.id||revision!==editRevision)return;const updated={...c,pvpUse:draftPvpUse,species:p.id,iv,trainer,observed,...state,level:undefined,max:undefined,threshold,cpFloor,fast:data.fast,charged:data.charged,confirmed:true,preview:r.previews.map(x=>({name:x.name,cap:x.cap,state:x.state,percentile:x.percentile}))};if(persist){await save(updated);selected=updated;try{if(cal)localStorage.setItem('go-lens-cal',JSON.stringify(cal))}catch{}}renderResults($('#results'),r,{...data,level,inference,db,card:updated,onFlag:value=>{if(editing)draftPvpUse=value},onTable:async candidate=>calculate({mode:'table',p:db.pokemon.find(x=>x.id===candidate.species),cap:candidate.cap,max:50})});if(persist){editing=false;editRevision++}applyEditMode();}catch(e){$('#error').textContent=e.message}finally{saving=false;applyEditMode();$('#analyze').disabled=false;$('#analyze').textContent='수정 저장 / 분석하기'}}

$('#analyze').onclick=()=>analyze();
function download(data,name,type){const url=URL.createObjectURL(new Blob([data],{type})),a=el('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000)}
$('#download').onclick=()=>{const a=el('a');a.href=selected.image;a.download=`go-lens-${selected.id}.jpg`;a.click()};
$('#delete').onclick=async()=>{if(!editing)return;if(!selected||!confirm('이 카드와 스크린샷을 기기에서 삭제할까요?'))return;try{await transaction('readwrite',s=>s.delete(selected.id))}catch{}cards=cards.filter(c=>c.id!==selected.id);$('#detail').close();render()};
$('#clear').onclick=async()=>{if(busy){status('분석을 중지한 뒤 삭제하세요.');return}if(!confirm('이 기기의 모든 분석 카드와 보정 좌표를 삭제할까요? 내보낸 백업은 별도로 남습니다.'))return;try{await transaction('readwrite',s=>s.clear())}catch{}cards=[];cal=null;try{localStorage.removeItem('go-lens-cal')}catch{}render();status('기기에 저장된 카드와 보정 좌표를 삭제했습니다.')};
$('#export').onclick=()=>download(JSON.stringify({schema:1,exportedAt:new Date().toISOString(),cards}),`go-lens-${new Date().toISOString().slice(0,10)}.json`,'application/json');
$('#restore').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>100*1024*1024)throw Error('백업은 100MB 이하로 선택하세요.');const b=JSON.parse(await f.text());if(b.schema!==1||!Array.isArray(b.cards)||b.cards.length>500)throw Error('지원하지 않는 백업입니다.');for(const c of b.cards){if(typeof c.id!=='string'||c.id.length>100||typeof c.image!=='string'||!/^data:image\/(jpeg|png);base64,[A-Za-z0-9+/=]+$/.test(c.image)||c.image.length>8e6)throw Error('백업 카드의 이미지 형식이 잘못되었습니다.');if(c.iv&&(!Array.isArray(c.iv)||c.iv.length!==3||c.iv.some(n=>!Number.isInteger(n)||n<0||n>15)))throw Error('잘못된 IV가 포함되어 있습니다.');if(c.species&&!db.pokemon.some(p=>p.id===c.species))throw Error('현재 DB에 없는 종·폼이 있습니다.')}for(const c of b.cards)await save(c);status(`${b.cards.length}개 카드 복원 완료`)}catch(e){status(e.message)}finally{e.target.value=''}};
const canvas=document.createElement('canvas');function frame(source){const w=source.videoWidth||source.naturalWidth,h=source.videoHeight||source.naturalHeight;if(!w||!h)throw Error('영상/이미지 프레임을 읽지 못했습니다.');canvas.width=Math.min(w,720);canvas.height=Math.round(h*canvas.width/w);const ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.drawImage(source,0,0,canvas.width,canvas.height);return ctx.getImageData(0,0,canvas.width,canvas.height)}
async function addFrame(source,time=0,force=false){const pixels=frame(source),r=detect(pixels,cal),sig=signature(pixels);if(!force&&!r.candidate)return false;if(!force&&cards.slice(-30).some(c=>c.sig&&distance(c.sig,sig)<.12))return false;await save({id:crypto.randomUUID(),image:canvas.toDataURL('image/jpeg',.84),time,iv:r.candidate?r.iv:null,confidence:force?'수동 저장 / 확인 필요':r.confidence,sig,confirmed:false});return true}
function waitVideo(v,event,action){return new Promise((resolve,reject)=>{const timer=setTimeout(()=>finish(Error('영상을 읽는 시간이 초과되었습니다. MP4 또는 스크린샷으로 다시 시도하세요.')),20000),ok=()=>finish(),bad=()=>finish(Error('이 브라우저가 영상 코덱을 재생하지 못합니다. H.264 MP4 또는 스크린샷을 사용하세요.'));function finish(err){clearTimeout(timer);v.removeEventListener(event,ok);v.removeEventListener('error',bad);err?reject(err):resolve()}v.addEventListener(event,ok,{once:true});v.addEventListener('error',bad,{once:true});action()})}
$('#stop').onclick=()=>{cancel=true;status('현재 프레임 처리 후 중지합니다. 저장된 카드는 유지됩니다.')};
$('#capture').onclick=async()=>{if(busy)return;try{await addFrame($('#video'),$('#video').currentTime,true);status('현재 장면을 저장했습니다. 카드를 선택해 교정하세요.')}catch(e){status(e.message)}};
async function importFiles(files){if(busy)return;try{trainerCap(Number($('#trainer').value))}catch{status('먼저 트레이너 레벨(1–80)을 입력한 뒤 파일을 선택하세요.');$('#files').value='';return}busy=true;cancel=false;$('#files').disabled=true;$('#stop').hidden=false;$('#progress').hidden=false;let n=0;try{for(const file of files){if(cancel)break;if(file.type.startsWith('image/')){const url=URL.createObjectURL(file);try{const img=await loadImage(url);await addFrame(img,0,true);n++}finally{URL.revokeObjectURL(url)}continue}if(!file.type.startsWith('video/')&&!/\.(mp4|mov|m4v)$/i.test(file.name)){status('영상 또는 이미지 파일만 선택하세요.');continue}if(file.size>1024**3)throw Error('영상은 1GB 이하로 나누어 선택하세요.');if(videoURL)URL.revokeObjectURL(videoURL);videoURL=URL.createObjectURL(file);const v=$('#video');await waitVideo(v,'loadedmetadata',()=>{v.src=videoURL;v.load()});$('#videoPanel').hidden=false;if(!Number.isFinite(v.duration)||v.duration>900)throw Error('MVP는 최대 15분 영상까지 지원합니다. 짧게 나누어 주세요.');v.pause();const step=Number($('#interval').value);for(let t=.05;t<v.duration&&!cancel;t+=step){await waitVideo(v,'seeked',()=>v.currentTime=Math.min(t,v.duration-.001));if(await addFrame(v,t))n++;$('#progress').value=t/v.duration;status(`${Math.floor(t)} / ${Math.floor(v.duration)}초 확인 / 새 카드 ${n}개 / 화면을 열어 두세요.`);await new Promise(r=>setTimeout(r,0))}}status(`${cancel?'중지':'분석 완료'} / 새 카드 ${n}개. ${n?'카드에서 종과 IV를 확인하세요.':'탐지된 화면이 없으면 미리보기에서 직접 저장하거나 스크린샷을 추가하세요.'}`)}catch(e){status(e.message)}finally{busy=false;$('#files').disabled=false;$('#files').value='';$('#stop').hidden=true;$('#progress').hidden=true}}
$('#files').onchange=e=>importFiles([...e.target.files]);const drop=$('#drop');drop.ondragover=e=>{e.preventDefault();drop.classList.add('drag')};drop.ondragleave=()=>drop.classList.remove('drag');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('drag');importFiles([...e.dataTransfer.files])};
$('#demo').onclick=async()=>{if(!$('#trainer').value)$('#trainer').value=40;const cv=document.createElement('canvas');cv.width=390;cv.height=720;const c=cv.getContext('2d');c.fillStyle='#e9eee0';c.fillRect(0,0,390,720);c.fillStyle='#456347';c.font='20px sans-serif';c.fillText('CP1400',135,65);c.font='16px sans-serif';c.fillText('예제 / 마릴리',40,100);c.font='100px sans-serif';c.fillText('◎',145,240);c.fillStyle='#fffdf5';c.fillRect(28,350,334,300);c.fillStyle='#3e5c42';c.font='18px sans-serif';c.fillText('EXAMPLE / 0 / 15 / 15',48,390);['ATTACK','DEFENSE','HP'].forEach((t,i)=>{c.fillStyle='#50684a';c.font='12px sans-serif';c.fillText(t,48,428+i*60);c.fillStyle='#e3e5d9';c.fillRect(48,440+i*60,270,10);if(i){c.fillStyle='#ec9a48';c.fillRect(48,440+i*60,270,10)}});await save({id:crypto.randomUUID(),image:cv.toDataURL('image/jpeg'),demo:true,species:'azumarill',iv:[0,15,15],observed:{cp:1400},trainer:40,confirmed:true,confidence:'예제 데이터 / 실제 포켓몬 아님',time:0});status('예제 카드를 추가했습니다. 선택하면 계산 결과를 볼 수 있습니다.')};


$('.editor').addEventListener('input',e=>{if(!editing)return;editRevision++;if(!e.target.closest('#results'))$('#results').replaceChildren()});

const cpCanvas=document.createElement('canvas'),templates=digitTemplates(document.createElement('canvas'));let cpPoints=null;
function syncIV(){for(const k of ['atk','def','hp'])$('#'+k+'-value').textContent=$('#'+k).value}
function updateEstimate(){const p=db.pokemon.find(p=>p.id===$('#species').value);if(!p){$('#level-estimate').textContent='종·폼을 선택하면 CP·IV로 레벨을 추정합니다.';return}try{const iv=['atk','def','hp'].map(k=>Number($('#'+k).value)),r=inferLevel(db,p,iv,Number($('#trainer').value),{cp:$('#observed-cp').value,hp:$('#observed-hp').value},getState());$('#level-estimate').textContent=r.message+' / 일반 강화 상한 '+r.cap+' / PvP 잠재력은 레벨 50 기준';}catch(e){$('#level-estimate').textContent=e.message}}
function readCP(rect={x0:.2,y0:.065,x1:.82,y1:.22}){if(!imageObj)return;$('#results').replaceChildren();const w=imageObj.naturalWidth,h=imageObj.naturalHeight;cpCanvas.width=500;cpCanvas.height=Math.min(500,Math.max(24,Math.round((rect.y1-rect.y0)*h/((rect.x1-rect.x0)*w)*500)));const ctx=cpCanvas.getContext('2d',{willReadFrequently:true});ctx.drawImage(imageObj,rect.x0*w,rect.y0*h,(rect.x1-rect.x0)*w,(rect.y1-rect.y0)*h,0,0,cpCanvas.width,cpCanvas.height);const r=recognizeCP(ctx.getImageData(0,0,cpCanvas.width,cpCanvas.height),templates);if(r){$('#observed-cp').value=r.cp;$('#calhelp').textContent='CP 자동 판독 '+r.cp+' / '+r.confidence+' / 원본과 비교해 주세요.'}else $('#calhelp').textContent='CP를 읽지 못했습니다. CP 영역을 선택하거나 화면의 CP를 교정 입력하세요.';updateEstimate();return r}
try{$('#trainer').value=Number(localStorage.getItem('go-lens-trainer'))||''}catch{}
$('#trainer').onchange=()=>{try{trainerCap(Number($('#trainer').value));localStorage.setItem('go-lens-trainer',$('#trainer').value);if(selected){updateEstimate();$('#results').replaceChildren()}}catch(e){status(e.message)}};
for(const k of ['atk','def','hp'])$('#'+k).oninput=()=>{syncIV();$('#iv-confirm').checked=true;updateEstimate()};for(const k of ['observed-cp','observed-hp'])$('#'+k).oninput=updateEstimate;
for(const k of ['shadow','purified','lucky'])$('#state-'+k).onchange=()=>{if($('#state-'+k).checked){if(k==='shadow'){$('#state-purified').checked=false;$('#state-lucky').checked=false}else $('#state-shadow').checked=false}const f=$('#fast').value,c=$('#charged').value;moveOptions(db.pokemon.find(p=>p.id===$('#species').value),f,c);updateEstimate()};
$('#cp-read').onclick=()=>readCP();$('#cp-crop').onclick=()=>{cpPoints=[];calpoints=null;$('#calhelp').textContent='CP 숫자만 포함하는 영역의 왼쪽 위, 오른쪽 아래를 차례로 클릭하세요.'};const ivClick=$('#shot').onclick;$('#shot').onclick=e=>{if(!editing)return;if(!cpPoints)return ivClick(e);const cv=$('#shot'),r=cv.getBoundingClientRect(),scale=Math.min(r.width/cv.width,r.height/cv.height),dw=cv.width*scale,dh=cv.height*scale,x=(e.clientX-r.left-(r.width-dw)/2)/dw,y=(e.clientY-r.top-(r.height-dh)/2)/dh;if(x<0||x>1||y<0||y>1)return;cpPoints.push([x,y]);if(cpPoints.length===1){$('#calhelp').textContent='CP 숫자 영역의 오른쪽 아래를 클릭하세요.';return}const [a,b]=cpPoints;cpPoints=null;if(b[0]-a[0]<.03||b[1]-a[1]<.005){$('#calhelp').textContent='영역이 너무 작습니다. CP 영역을 다시 선택하세요.';return}readCP({x0:a[0],y0:a[1],x1:b[0],y1:b[1]})};




function applyEditMode(){const dialog=$('#detail');dialog.classList.toggle('editing',editing);for(const control of dialog.querySelectorAll('.editor input,.editor select,.editor textarea'))control.disabled=!editing||saving;for(const id of ['calibrate','cp-crop','cp-read','delete'])$('#'+id).hidden=!editing;$('#analyze').hidden=!editing;$('#edit').hidden=editing;$('#cancel-edit').hidden=!editing;$('#cancel-edit').disabled=saving;for(const id of ['calibrate','cp-crop','cp-read','delete'])$('#'+id).disabled=saving;$('#edit-note').textContent=editing?'수정 중입니다. 수정 저장을 눌러야 변경사항이 반영됩니다.':'조회 모드입니다. 정보를 바꾸려면 수정하기를 누르세요.';if(editing&&!saving){const f=$('#fast').value,c=$('#charged').value;moveOptions(db.pokemon.find(p=>p.id===$('#species').value),f,c)}}
$('#edit').onclick=()=>{if(!selected)return;editCalSnapshot=cal?structuredClone(cal):null;editing=true;editRevision++;applyEditMode()};
$('#cancel-edit').onclick=async()=>{if(!selected||saving)return;cal=editCalSnapshot?structuredClone(editCalSnapshot):null;const saved=cards.find(c=>c.id===selected.id)||selected;await open(saved)};
$('#detail').addEventListener('close',()=>{if(editing&&!saving)cal=editCalSnapshot?structuredClone(editCalSnapshot):null;editing=false;editRevision++;calpoints=null;cpPoints=null});
